let tasks = []; let taskBaseline = []; let taskBaseSha; let sideworks = []; let collects = []; let collectBaseline = []; let collectBaseSha; let topics = []; let topicBaseline = []; let topicBaseSha; let organizeTarget = null; let organizePendingNote = null;
