// 仅在本次页面会话中保存展示层的展开状态，不写入用户数据或 localStorage。
const expandedProjects = new Set(); const expandedSideworks = new Set(); const expandedTasks = new Set(); const expandedNotes = new Set();

function showStatus(node, message, kind = '') { node.textContent = message; node.dataset.kind = kind; }
function hasToken() { return Boolean(tokenInput.value.trim()); }
function requireToken(statusNode) { if (hasToken()) return true; showStatus(statusNode, '请先在设置中填写 GitHub 细粒度 PAT。', 'error'); return false; }
function showWriteStatus(node) { showStatus(node, '保存中…'); }
function setSaved(node, message) { showStatus(node, message, 'success'); window.setTimeout(() => { if (node.dataset.kind === 'success') showStatus(node, ''); }, 3500); }
function isNetworkError(error) { return !(error instanceof GitHubRequestError) && (error instanceof TypeError || /network|fetch/i.test(error.message || '')); }
function showError(node, error) { if (isNetworkError(error)) showStatus(node, '现在连不上网。你的改动还没保存，恢复网络后再点一次保存。', 'error'); else showStatus(node, error.message || String(error), 'error'); }
function showUpdateBar(worker) { if (document.querySelector('#update-bar')) return; const bar = document.createElement('section'); bar.id = 'update-bar'; bar.className = 'update-bar'; bar.setAttribute('role', 'status'); const message = document.createElement('span'); message.textContent = '有新版本可用'; const refresh = makeButton('立即刷新', 'primary', () => { if (reloadForUpdate) return; reloadForUpdate = true; worker.postMessage({ type: 'SKIP_WAITING' }); }); const later = makeButton('稍后', 'secondary', () => bar.remove()); bar.append(message, refresh, later); document.body.append(bar); }
function showWaitingUpdate(registration) { if (!registration.waiting || !navigator.serviceWorker.controller) return false; showUpdateBar(registration.waiting); return true; }
function watchForUpdate(registration) { registration.addEventListener('updatefound', () => { const worker = registration.installing; if (!worker) return; worker.addEventListener('statechange', () => { if (worker.state === 'installed') showWaitingUpdate(registration); }); }); }
async function checkForUpdateOnFocus() { if (!serviceWorkerRegistration || Date.now() - lastUpdateCheckAt < 30000) return; lastUpdateCheckAt = Date.now(); try { await serviceWorkerRegistration.update(); showWaitingUpdate(serviceWorkerRegistration); } catch (error) { console.error('Service Worker 更新检查失败：', error); } }
async function checkForUpdateManually() { if (!serviceWorkerRegistration) { showStatus(result, '当前浏览器不支持离线更新。', 'error'); return; } showStatus(result, '正在检查更新…'); try { await serviceWorkerRegistration.update(); if (showWaitingUpdate(serviceWorkerRegistration)) { showStatus(result, '发现新版本，请在顶部提示条刷新。', 'success'); return; } showStatus(result, `已是最新版本（${APP_VERSION}）`, 'success'); } catch (error) { showStatus(result, `检查更新失败：${error.message || String(error)}`, 'error'); } }
function openSettings() { switchView('settings'); tokenInput.focus(); }
function handleWriteError(node, error, { reload, overwrite } = {}) { if (error instanceof GitHubRequestError && error.status === 401) { showStatus(node, error.message, 'error'); const button = makeButton('去设置页', 'secondary', openSettings); node.append(document.createTextNode(' '), button); return; } if (!(error instanceof GitHubRequestError) || error.status !== 409) { showError(node, error); return; } const dialog = document.querySelector('#conflict-dialog'); dialog.showModal(); dialog.querySelector('[data-action="cancel"]').onclick = () => dialog.close(); dialog.querySelector('[data-action="reload"]').onclick = async () => { dialog.close(); await reload?.(); }; dialog.querySelector('[data-action="overwrite"]').onclick = async () => { if (!window.confirm('确定要用你的版本覆盖吗？对方的改动会丢失。')) return; dialog.close(); await overwrite?.(); }; }
function addTokenGuide() { const guide = document.createElement('ol'); guide.className = 'notice'; guide.innerHTML = '<li>去 GitHub → Settings → Developer settings → Personal access tokens → Fine-grained tokens。</li><li>选择 Generate new token。</li><li>Repository access 选 <strong>Only select repositories</strong>，只勾 penemue。</li><li>Permissions → Repository permissions → <strong>Contents: Read and write</strong>（Metadata 会自动变 Read，别动）。</li><li>生成后复制粘贴到上面的输入框。</li>'; const risk = document.querySelector('.settings .notice'); risk.after(guide); risk.textContent += ' token 有有效期，过期后需要重新生成并填写。'; }
function savedSha(data, fallback) { return data?.content?.sha || fallback; }
function createNav() { for (const nav of document.querySelectorAll('[data-nav]')) for (const [view, label, compact, sidebarOnly] of navItems) { if (nav.classList.contains('bottom-tabs') && sidebarOnly) continue; const node = document.createElement('button'); node.type = 'button'; node.className = 'nav-button'; node.classList.toggle('active', view === 'today'); node.dataset.target = view; node.textContent = nav.classList.contains('bottom-tabs') ? compact : label; nav.append(node); } }
function switchView(view) { for (const element of document.querySelectorAll('.view')) element.classList.toggle('active', element.dataset.view === view); for (const node of document.querySelectorAll('.nav-button')) node.classList.toggle('active', node.dataset.target === view); }
function makeButton(label, className, action) { const node = document.createElement('button'); node.type = 'button'; node.className = className; node.textContent = label; node.addEventListener('click', action); return node; }
function inputField(type, value, change, placeholder = '') { const node = document.createElement('input'); node.type = type; node.value = value ?? ''; node.placeholder = placeholder; node.addEventListener('change', () => change(type === 'number' ? Number(node.value) : node.value)); return node; }
function renderEmptyState(holder, message) { const empty = document.createElement('div'); empty.className = 'empty-state'; const glow = document.createElement('span'); glow.className = 'empty-state-glow'; const horizon = document.createElement('span'); horizon.className = 'empty-state-horizon'; const text = document.createElement('p'); text.textContent = message; empty.append(glow, horizon, text); holder.append(empty); }
function mergeLatest(latestRecords, localRecords, baseline, kind) { const local = localRecords.filter((item) => item.kind === kind); const unused = [...local]; const remaining = [...baseline]; const merged = []; for (const record of latestRecords) { if (record.kind !== kind) { merged.push(record); continue; } const localIndex = unused.findIndex((item) => item.raw === record.raw); if (localIndex !== -1) { merged.push(unused.splice(localIndex, 1)[0]); remaining.splice(remaining.indexOf(record.raw), 1); continue; } const baseIndex = remaining.indexOf(record.raw); if (baseIndex !== -1) { remaining.splice(baseIndex, 1); continue; } merged.push(record); } if (unused.length && merged.length && !merged.at(-1).ending) merged.at(-1).ending = '\n'; return [...merged, ...unused]; }

// GitHub 时间戳按日期前缀处理，不交给 Date 解析，以免时区换日。
function shortCommitDate(value, today = localToday()) { const [year, month, day] = String(value || '').slice(0, 10).split('-'); if (!/^\d{4}$/.test(year) || !/^\d{2}$/.test(month) || !/^\d{2}$/.test(day)) return '—'; const date = `${Number(month)}-${Number(day)}`; return year === today.slice(0, 4) ? date : `${year}-${date}`; }

function renderProjects(cards) { const holder = document.querySelector('#project-cards'); holder.replaceChildren(); const fields = ['type', 'created', 'updated', 'tags', 'repo', 'last_commit_date', 'last_commit_msg']; for (const cardData of cards) { const { file, data } = cardData; const isExpanded = expandedProjects.has(file.path); const card = document.createElement('article'); card.className = `project-card${isExpanded ? ' expanded' : ''}`; const header = document.createElement('div'); header.className = 'project-summary'; const title = document.createElement('h2'); title.textContent = data.title || file.name; const status = document.createElement('span'); status.className = 'summary-badge'; status.textContent = data.status || '—'; header.append(title, status); const nextText = document.createElement('p'); nextText.className = 'project-next-summary'; nextText.textContent = `下一步：${data.next_step || '—'}`; const commit = document.createElement('p'); commit.className = 'project-commit-summary'; commit.textContent = `${shortCommitDate(data.last_commit_date)} · ${data.last_commit_msg || '暂无提交信息'}`; const toggle = makeButton(isExpanded ? '收起 ▴' : '详情 ▾', 'disclosure-button', () => { if (expandedProjects.has(file.path)) expandedProjects.delete(file.path); else expandedProjects.add(file.path); renderProjects(cards); }); const details = document.createElement('div'); details.className = 'project-details'; const list = document.createElement('dl'); for (const keyName of fields) { const key = document.createElement('dt'); key.textContent = keyName; const value = document.createElement('dd'); value.textContent = Array.isArray(data[keyName]) ? data[keyName].join('、') : (data[keyName] ?? ''); list.append(key, value); } const edit = document.createElement('label'); edit.className = 'project-next-step'; edit.textContent = 'next_step'; const next = inputField('text', data.next_step || '', () => {}, '下一步'); edit.append(next); details.append(list, edit, makeButton('保存 next_step', 'secondary', () => saveProjectNextStep(cardData, next.value))); card.append(header, nextText, commit, toggle, details); holder.append(card); } }
async function loadProjects() { const status = document.querySelector('#projects-status'); if (!requireToken(status)) return; showStatus(status, '正在读取项目卡与 DDL……'); try { const files = (await listFiles('projects')).filter((file) => file.name.endsWith('.md')); const cards = await Promise.all(files.map(async (file) => { const source = await readFile(file.path); return { file, source: source?.text || '', baseSha: source?.sha, data: parseFrontmatter(source?.text || '').data }; })); renderProjects(cards); await loadDeadlineSources(); setSaved(status, `已读取 ${cards.length} 张项目卡和 DDL。`); } catch (error) { showError(status, error); } }
async function saveProjectNextStep(card, nextStep, force = false) { const status = document.querySelector('#projects-status'); if (!requireToken(status)) return; showWriteStatus(status); try { const baseSha = force ? (await readFile(card.file.path))?.sha : card.baseSha; const text = updateProjectNextStep(card.source, nextStep, localToday()); const data = await writeFile(card.file.path, text, baseSha); card.source = text; card.baseSha = savedSha(data, baseSha); card.data = parseFrontmatter(text).data; setSaved(status, '已保存 next_step；其余字段保持原样。'); } catch (error) { handleWriteError(status, error, { reload: loadProjects, overwrite: () => saveProjectNextStep(card, nextStep, true) }); } }

function renderTasks() { taskList.replaceChildren(); const records = tasks.filter((item) => item.kind === 'task'); if (!records.length) { renderEmptyState(taskList, '还没有待办。'); return; } const today = localToday(); for (const task of records) { const taskKey = task.title; const isExpanded = expandedTasks.has(taskKey); const row = document.createElement('div'); row.className = `task-row${task.completed ? ' completed' : ''}${isExpanded ? ' expanded' : ''}`; const check = document.createElement('input'); check.type = 'checkbox'; check.checked = task.completed; check.addEventListener('change', () => optimisticTaskChange(task, 'completed', check.checked)); const title = document.createElement('div'); title.className = 'task-title'; title.textContent = task.title; const meta = document.createElement('div'); meta.className = 'task-summary-meta'; for (const text of [task.category || '未分类', task.priority || '普通', task.dueDate || '无 DDL']) { const badge = document.createElement('span'); badge.className = 'summary-badge'; badge.textContent = text; meta.append(badge); } const expand = makeButton(isExpanded ? '收起' : '⋯', 'task-expand-button', () => { if (expandedTasks.has(taskKey)) expandedTasks.delete(taskKey); else expandedTasks.add(taskKey); renderTasks(); }); const dueInput = inputField('date', task.dueDate, (value) => updateTask(task, { dueDate: value })); dueInput.className = 'due'; const categoryInput = inputField('text', task.category, (value) => updateTask(task, { category: value }), '分类'); categoryInput.className = 'category'; const planToday = makeButton(task.plannedDate === today ? '已加入今天' : '加入今天', 'task-today-button', () => optimisticTaskChange(task, 'plannedDate', task.plannedDate === today ? '' : today)); planToday.classList.toggle('selected', task.plannedDate === today); row.addEventListener('dblclick', () => { if (expandedTasks.has(taskKey)) expandedTasks.delete(taskKey); else expandedTasks.add(taskKey); renderTasks(); }); row.append(check, title, meta, expand, dueInput, categoryInput, priorityField(task), planToday, makeButton('×', 'icon-button', () => optimisticDeleteTask(task, taskKey))); taskList.append(row); } }
function priorityField(task) { const select = document.createElement('select'); select.className = 'priority'; for (const value of ['', '高', '中', '低']) { const option = document.createElement('option'); option.value = value; option.textContent = value || '优先级'; option.selected = value === task.priority; select.append(option); } select.addEventListener('change', () => updateTask(task, { priority: select.value })); return select; }
async function loadTasks(status = true) { if (!requireToken(tasksStatus)) { renderToday(); return false; } if (status) showStatus(tasksStatus, '正在读取 tasks.md……'); try { const file = await readFile('tasks.md'); tasks = parseTasks(file?.text || ''); taskBaseSha = file?.sha; taskBaseline = tasks.filter((item) => item.kind === 'task').map((item) => item.raw); renderTasks(); renderDeadlineReminders(); renderCalendar(); renderToday(); if (status) setSaved(tasksStatus, file ? '已读取 tasks.md。' : 'tasks.md 尚不存在；新增待办时会创建。'); return true; } catch (error) { if (status) showError(tasksStatus, error); return false; } }
async function saveTasks(force = false) { if (!requireToken(tasksStatus)) return; showWriteStatus(tasksStatus); try { const baseSha = force ? (await readFile('tasks.md'))?.sha : taskBaseSha; const text = serializeTasks(tasks); const data = await writeFile('tasks.md', text, baseSha); taskBaseSha = savedSha(data, baseSha); tasks = parseTasks(text); taskBaseline = tasks.filter((item) => item.kind === 'task').map((item) => item.raw); renderTasks(); renderDeadlineReminders(); renderCalendar(); renderToday(); setSaved(tasksStatus, baseSha ? '已保存 tasks.md。' : '已创建并保存 tasks.md。'); } catch (error) { handleWriteError(tasksStatus, error, { reload: loadTasks, overwrite: () => saveTasks(true) }); } }
function updateTask(task, changes) { Object.assign(task, changes); saveTasks(); }
function refreshTaskViews() { renderTasks(); renderDeadlineReminders(); renderCalendar(); renderToday(); }
function optimisticTaskChange(task, field, value) { const before = task[field]; task[field] = value; refreshTaskViews(); showWriteStatus(tasksStatus); enqueueWrite('tasks.md', () => ({ content: serializeTasks(tasks) }), () => taskBaseSha, (sha) => { taskBaseSha = sha; }, writeFile).then(() => setSaved(tasksStatus, '已保存')).catch((error) => { if (task[field] === value) task[field] = before; refreshTaskViews(); showError(tasksStatus, error); tasksStatus.append(document.createTextNode(' 刚才那次修改已撤回。')); }); }
function optimisticDeleteTask(task, taskKey) { const index = tasks.indexOf(task); tasks.splice(index, 1); expandedTasks.delete(taskKey); refreshTaskViews(); showWriteStatus(tasksStatus); enqueueWrite('tasks.md', () => ({ content: serializeTasks(tasks) }), () => taskBaseSha, (sha) => { taskBaseSha = sha; }, writeFile).then(() => setSaved(tasksStatus, '已保存')).catch((error) => { if (!tasks.includes(task)) tasks.splice(index, 0, task); refreshTaskViews(); showError(tasksStatus, error); tasksStatus.append(document.createTextNode(' 刚才那次修改已撤回。')); }); }
function quickTaskResult() { return parseQuickInput(quickTaskInput.value, localToday()); }
function renderQuickTaskPreview() { const parsed = quickTaskResult(); const detected = [parsed.dueDate, parsed.category, parsed.priority].filter(Boolean); quickTaskPreview.hidden = !detected.length; quickTaskRawButton.hidden = !detected.length; if (!detected.length) return parsed; quickTaskDetected.textContent = `识别：${detected.join(' · ')}`; quickTaskTitle.textContent = `正文：${parsed.title || '（未填写正文）'}`; return parsed; }
function addQuickTask(raw = false) { if (!requireToken(tasksStatus)) return; const original = quickTaskInput.value.trim(); const parsed = quickTaskResult(); const fields = raw ? { title: original } : parsed; if (!fields.title) { showStatus(tasksStatus, '请先填写待办正文。', 'error'); quickTaskInput.focus(); return; } tasks.push(createTask({ title: fields.title, dueDate: fields.dueDate || '', category: fields.category || '', priority: fields.priority || '' })); quickTaskInput.value = ''; renderQuickTaskPreview(); quickTaskInput.focus(); saveTasks(); }

async function loadSideworks(status = true) { if (!requireToken(sideworkStatus)) { renderToday(); return false; } if (status) showStatus(sideworkStatus, '正在读取 sidework/……'); try { const files = (await listFiles('sidework')).filter((file) => file.name.endsWith('.md')); sideworks = await Promise.all(files.map(async (file) => { const source = await readFile(file.path); return { file, baseSha: source?.sha, ...parseSidework(source?.text || '') }; })); sideworks.sort((a, b) => { if ((a.data.status === 'done') !== (b.data.status === 'done')) return a.data.status === 'done' ? 1 : -1; if (!a.data.due) return 1; if (!b.data.due) return -1; return a.data.due.localeCompare(b.data.due); }); renderSideworks(); renderDeadlineReminders(); renderCalendar(); renderToday(); if (status) setSaved(sideworkStatus, `已读取 ${sideworks.length} 单副业。`); return true; } catch (error) { if (status) showError(sideworkStatus, error); return false; } }
function renderSideworks() { sideworkList.replaceChildren(); if (!sideworks.length) { renderEmptyState(sideworkList, '还没有副业单。'); return; } for (const record of sideworks) { const { data } = record; const isExpanded = expandedSideworks.has(record.file.path); const card = document.createElement('article'); card.className = `sidework-card${data.status === 'done' ? ' completed' : ''}${isExpanded ? ' expanded' : ''}`; const summary = document.createElement('div'); summary.className = 'sidework-summary'; const title = document.createElement('h2'); title.textContent = data.title || record.file.name; const meta = document.createElement('p'); meta.className = 'sidework-summary-meta'; meta.textContent = `${data.due || '未定 DDL'} 交 · ¥${data.price || 0} · ${data.paid ? '已回款' : '未回款'}`; const toggle = makeButton(isExpanded ? '收起 ▴' : '详情 ▾', 'disclosure-button', () => { if (expandedSideworks.has(record.file.path)) expandedSideworks.delete(record.file.path); else expandedSideworks.add(record.file.path); renderSideworks(); }); summary.append(title, meta, toggle); const details = document.createElement('div'); details.className = 'sidework-details'; const grid = document.createElement('div'); grid.className = 'sidework-fields'; const fields = [['标题', 'title', 'text'], ['甲方', 'client', 'text'], ['平台', 'platform', 'text'], ['篇数', 'count', 'number'], ['价格', 'price', 'number'], ['截止日', 'due', 'date'], ['标签', 'tags', 'text']]; for (const [label, key, type] of fields) { const wrap = document.createElement('label'); wrap.textContent = label; wrap.append(inputField(type, key === 'tags' ? (data.tags || []).join(', ') : data[key], (value) => { data[key] = key === 'tags' ? value.split(',').map((tag) => tag.trim()).filter(Boolean) : value; }, label)); grid.append(wrap); } const statusWrap = document.createElement('label'); statusWrap.textContent = '状态'; const state = document.createElement('select'); for (const value of ['active', 'done', 'paused', 'archived']) { const option = document.createElement('option'); option.value = value; option.textContent = value; option.selected = value === data.status; state.append(option); } state.addEventListener('change', () => { data.status = state.value; }); statusWrap.append(state); const paidWrap = document.createElement('label'); paidWrap.className = 'check-field'; const paid = document.createElement('input'); paid.type = 'checkbox'; paid.checked = Boolean(data.paid); paid.addEventListener('change', () => { data.paid = paid.checked; }); paidWrap.append(paid, document.createTextNode(' 已回款')); grid.append(statusWrap, paidWrap); const savedMeta = document.createElement('p'); savedMeta.className = 'sidework-meta'; savedMeta.textContent = `建立：${data.created || '—'}　更新：${data.updated || '—'}`; const actions = document.createElement('div'); actions.className = 'sidework-actions'; actions.append(makeButton('保存字段', 'primary', () => saveSidework(record)), makeButton(data.status === 'done' ? '重新打开' : '标记完成', 'secondary', () => { data.status = data.status === 'done' ? 'active' : 'done'; saveSidework(record); }), makeButton(data.paid ? '取消回款' : '标记回款', 'secondary', () => { data.paid = !data.paid; saveSidework(record); })); details.append(grid, savedMeta, actions); card.append(summary, details); sideworkList.append(card); } }
async function saveSidework(record, force = false) { if (!requireToken(sideworkStatus)) return; showWriteStatus(sideworkStatus); try { const baseSha = force ? (await readFile(record.file.path))?.sha : record.baseSha; const data = { ...record.data, type: 'sidework', created: record.data.created, updated: localToday() }; const text = serializeSidework({ data, unknownLines: record.unknownLines, body: record.body }); const saved = await writeFile(record.file.path, text, baseSha); Object.assign(record, { data, baseSha: savedSha(saved, baseSha) }); renderSideworks(); renderDeadlineReminders(); renderCalendar(); setSaved(sideworkStatus, '已保存副业单；正文与未知字段保持原样。'); } catch (error) { handleWriteError(sideworkStatus, error, { reload: loadSideworks, overwrite: () => saveSidework(record, true) }); } }
async function createSidework(form) { if (!requireToken(sideworkStatus)) return; const formData = new FormData(form); const today = localToday(); showWriteStatus(sideworkStatus); try { const files = (await listFiles('sidework')).filter((file) => file.name.endsWith('.md')); const data = { ...sideworkDefaults(today), title: formData.get('title').trim(), client: formData.get('client').trim(), platform: formData.get('platform').trim(), count: Number(formData.get('count')) || 0, price: Number(formData.get('price')) || 0, due: formData.get('due') || '' }; const path = sideworkFilename(today, data.title, files.map((file) => file.path)); await writeFile(path, serializeSidework({ data, body: '' })); form.reset(); await loadSideworks(); setSaved(sideworkStatus, `已新建 ${path}。`); } catch (error) { handleWriteError(sideworkStatus, error, { reload: loadSideworks, overwrite: () => createSidework(form) }); } }

function renderCollects() { collectList.replaceChildren(); const records = collects.filter((item) => item.kind === 'collect'); if (!records.length) { renderEmptyState(collectList, '还没有收集内容。'); return; } for (const record of records) { const row = document.createElement('article'); row.className = `collect-row${record.completed ? ' completed' : ''}`; const check = document.createElement('input'); check.type = 'checkbox'; check.checked = record.completed; check.addEventListener('change', () => optimisticCollectChange(record, check.checked)); const content = document.createElement('div'); content.className = 'collect-content'; content.textContent = record.content; const time = document.createElement('time'); time.textContent = record.createdAt; row.append(check, content, time, makeButton('整理成笔记', 'secondary', () => openNoteForm(record)), makeButton('×', 'icon-button', () => { collects = collects.filter((item) => item !== record); saveCollects(); })); collectList.append(row); } }
function optimisticCollectChange(record, value) { const before = record.completed; record.completed = value; renderCollects(); renderToday(); showWriteStatus(collectStatus); enqueueWrite('collect.md', () => ({ content: serializeCollect(collects) }), () => collectBaseSha, (sha) => { collectBaseSha = sha; }, writeFile).then(() => setSaved(collectStatus, '已保存')).catch((error) => { if (record.completed === value) record.completed = before; renderCollects(); renderToday(); showError(collectStatus, error); collectStatus.append(document.createTextNode(' 刚才那次修改已撤回。')); }); }
async function loadCollects(status = true) { if (!requireToken(collectStatus)) { renderToday(); return false; } if (status) showStatus(collectStatus, '正在读取 collect.md……'); try { const file = await readFile('collect.md'); collects = parseCollect(file?.text || ''); collectBaseSha = file?.sha; collectBaseline = collects.filter((item) => item.kind === 'collect').map((item) => item.raw); renderCollects(); renderToday(); if (status) setSaved(collectStatus, file ? '已读取 collect.md。' : 'collect.md 尚不存在；记一条时会创建。'); return true; } catch (error) { if (status) showError(collectStatus, error); return false; } }
async function saveCollects(force = false) { if (!requireToken(collectStatus)) return; showWriteStatus(collectStatus); try { const baseSha = force ? (await readFile('collect.md'))?.sha : collectBaseSha; const text = serializeCollect(collects); const data = await writeFile('collect.md', text, baseSha); collectBaseSha = savedSha(data, baseSha); collects = parseCollect(text); collectBaseline = collects.filter((item) => item.kind === 'collect').map((item) => item.raw); renderCollects(); renderToday(); setSaved(collectStatus, baseSha ? '已保存 collect.md。' : '已创建并保存 collect.md。'); } catch (error) { handleWriteError(collectStatus, error, { reload: loadCollects, overwrite: () => saveCollects(true) }); } }
function openNoteForm(record) { organizeTarget = record; const form = document.querySelector('#note-form'); form.hidden = false; form.elements.title.value = record.content; form.elements.tags.value = ''; form.elements.title.focus(); }
async function organizeAsNote(form, force = false) { if (!organizeTarget || !requireToken(collectStatus)) return; showWriteStatus(collectStatus); try { if (!organizePendingNote) { const formData = new FormData(form); const today = localToday(); const files = (await listFiles('notes')).filter((file) => file.name.endsWith('.md')); const title = formData.get('title').trim(); const tags = formData.get('tags').split(',').map((tag) => tag.trim()).filter(Boolean); const path = markdownFilename('notes', today, title, files.map((file) => file.path)); const note = `---\ntype: note\ntitle: ${title}\ncreated: ${today}\nupdated: ${today}\nstatus: active\ntags: [${tags.join(', ')}]\n---\n\n${organizeTarget.content}\n`; await writeFile(path, note); organizePendingNote = { path }; } const baseSha = force ? (await readFile('collect.md'))?.sha : collectBaseSha; const remaining = collects.filter((item) => item !== organizeTarget); const data = await writeFile('collect.md', serializeCollect(remaining), baseSha); collects = remaining; collectBaseSha = savedSha(data, baseSha); const path = organizePendingNote.path; organizePendingNote = null; organizeTarget = null; form.hidden = true; setSaved(collectStatus, `已创建 ${path}，并移出收集箱。`); const go = makeButton('去看这篇笔记', 'secondary', () => { pendingNotePath = path; switchView('notes'); loadNotes(); }); collectStatus.append(document.createTextNode(' '), go); } catch (error) { handleWriteError(collectStatus, error, { reload: loadCollects, overwrite: () => organizeAsNote(form, true) }); } }

function appendHighlighted(node, text, query) { const lower = text.toLocaleLowerCase(); const needle = query.toLocaleLowerCase(); let start = 0; let index = lower.indexOf(needle, start); while (index !== -1) { node.append(document.createTextNode(text.slice(start, index))); const mark = document.createElement('mark'); mark.textContent = text.slice(index, index + query.length); node.append(mark); start = index + query.length; index = lower.indexOf(needle, start); } node.append(document.createTextNode(text.slice(start))); }
function noteSearchSnippet(note, query) { const body = note.body || ''; const index = body.toLocaleLowerCase().indexOf(query.toLocaleLowerCase()); if (query && index !== -1) return `${index > 20 ? '…' : ''}${body.slice(Math.max(0, index - 20), index + query.length + 20)}${index + query.length + 20 < body.length ? '…' : ''}`; return noteSummary(body).slice(0, 60) + (noteSummary(body).length > 60 ? '…' : ''); }
function renderNotes() { notesList.replaceChildren(); const query = document.querySelector('#notes-search').value.trim(); const lower = query.toLocaleLowerCase(); const sorted = [...notes].sort((a, b) => (b.data.updated || '').localeCompare(a.data.updated || '') || a.file.name.localeCompare(b.file.name)); const matched = sorted.filter((note) => !query || [note.data.title || '', ...(note.data.tags || []), note.body || ''].join('\n').toLocaleLowerCase().includes(lower)); document.querySelector('#notes-count').textContent = `${notes.length} 篇中匹配 ${matched.length} 篇`; if (!matched.length) { renderEmptyState(notesList, notes.length ? '没有匹配的笔记。' : '还没有笔记。在收集箱里把一条随手记整理成笔记，它就会出现在这里。'); return; } for (const note of matched) { const expanded = expandedNotes.has(note.file.path) || pendingNotePath === note.file.path; const card = document.createElement('article'); card.className = `note-card${expanded ? ' expanded' : ''}`; const header = document.createElement('div'); header.className = 'project-summary'; const title = document.createElement('h2'); if (query) appendHighlighted(title, note.data.title || note.file.name.replace(/\.md$/, ''), query); else title.textContent = note.data.title || note.file.name.replace(/\.md$/, ''); header.append(title); const meta = document.createElement('p'); meta.className = 'project-commit-summary'; meta.textContent = `更新 ${note.data.updated || '—'}${(note.data.tags || []).length ? ` · ${(note.data.tags || []).map((tag) => `#${tag}`).join(' ')}` : ''}`; const summary = document.createElement('p'); summary.className = 'project-next-summary'; const snippet = noteSearchSnippet(note, query); if (query) appendHighlighted(summary, snippet, query); else summary.textContent = snippet; const toggle = makeButton(expanded ? '收起 ▴' : '详情 ▾', 'disclosure-button', () => { if (expandedNotes.has(note.file.path)) expandedNotes.delete(note.file.path); else expandedNotes.add(note.file.path); pendingNotePath = null; renderNotes(); }); const details = document.createElement('div'); details.className = 'note-details'; const editor = document.createElement('textarea'); editor.value = note.body; editor.rows = 12; editor.className = 'note-editor'; details.append(editor, makeButton('保存', 'primary', () => saveNote(note, editor.value))); card.append(header, meta, summary, toggle, details); notesList.append(card); } pendingNotePath = null; }
async function loadNotes(force = false, confirmed = false) { if (!requireToken(notesStatus)) return; if (notesLoaded && !force) { renderNotes(); return; } showStatus(notesStatus, '正在读取笔记清单…'); try { const files = (await listFiles('notes')).filter((file) => file.name.endsWith('.md')); if (files.length > 50 && !confirmed) { showStatus(notesStatus, `notes/ 下有 ${files.length} 个文件，读取会发起 ${files.length} 次请求，可能较慢。`); notesStatus.append(document.createTextNode(' '), makeButton('继续', 'secondary', () => loadNotes(force, true))); return; } const cache = new Map(notes.map((note) => [note.file.path, note])); const loaded = []; for (let index = 0; index < files.length; index += 1) { const file = files[index]; showStatus(notesStatus, `正在读取 ${index + 1} / ${files.length}…`); const source = !force && cache.get(file.path); const result = source || await readFile(file.path); const text = source?.rawText || result?.text || ''; loaded.push({ file: { ...file, sha: result?.sha || source?.file.sha }, data: parseFrontmatter(text).data, rawText: text, body: parseFrontmatter(text).body }); } notes = loaded; notesLoaded = true; renderNotes(); setSaved(notesStatus, `已读取 ${notes.length} 篇笔记。`); } catch (error) { showError(notesStatus, error); } }
async function saveNote(note, body, force = false) { if (!requireToken(notesStatus)) return; showWriteStatus(notesStatus); const content = replaceNoteBody(note.rawText, body, localToday()); try { const baseSha = force ? (await readFile(note.file.path))?.sha : note.file.sha; const saved = await writeFile(note.file.path, content, baseSha); note.rawText = content; note.body = body; note.file.sha = savedSha(saved, baseSha); note.data = parseFrontmatter(content).data; renderNotes(); setSaved(notesStatus, '已保存'); } catch (error) { handleWriteError(notesStatus, error, { reload: () => loadNotes(true), overwrite: () => saveNote(note, body, true) }); } }
async function createNote(form) { if (!requireToken(notesStatus)) return; const data = new FormData(form); const title = data.get('title').trim(); if (!title) return; const tags = data.get('tags').split(',').map((tag) => tag.trim()).filter(Boolean); const today = localToday(); showWriteStatus(notesStatus); try { const files = await listFiles('notes'); const path = noteFilename(title, files.map((file) => file.path)); const content = `---\ntype: note\ntitle: ${title}\ncreated: ${today}\nupdated: ${today}\nstatus: active\ntags: [${tags.join(', ')}]\n---\n\n`; const saved = await writeFile(path, content); const note = { file: { name: path.split('/').at(-1), path, sha: savedSha(saved) }, data: parseFrontmatter(content).data, rawText: content, body: '' }; notes.push(note); expandedNotes.add(path); form.reset(); renderNotes(); setSaved(notesStatus, '已新建笔记'); } catch (error) { showError(notesStatus, error); } }

function renderTopics() { topicGroups.replaceChildren(); for (const status of ['待写', '写中', '已发']) { const section = document.createElement('section'); section.className = 'topic-group'; const title = document.createElement('h2'); title.textContent = status; section.append(title); const records = topics.filter((item) => item.kind === 'topic' && item.status === status); if (!records.length) renderEmptyState(section, '暂无选题。'); for (const record of records) { const row = document.createElement('div'); row.className = `topic-row${record.completed ? ' completed' : ''}`; const check = document.createElement('input'); check.type = 'checkbox'; check.checked = record.completed; check.addEventListener('change', () => { record.completed = check.checked; saveTopics(); }); const titleInput = inputField('text', record.title, (value) => { record.title = value; saveTopics(); }); const platform = inputField('text', record.platform, (value) => { record.platform = value; saveTopics(); }, '平台'); const state = document.createElement('select'); for (const value of ['待写', '写中', '已发']) { const option = document.createElement('option'); option.value = value; option.textContent = value; option.selected = value === record.status; state.append(option); } state.addEventListener('change', () => { record.status = state.value; saveTopics(); }); row.append(check, titleInput, platform, state, makeButton('×', 'icon-button', () => { topics = topics.filter((item) => item !== record); saveTopics(); })); section.append(row); } topicGroups.append(section); } }
async function loadTopics(status = true) { if (!requireToken(topicsStatus)) return false; if (status) showStatus(topicsStatus, '正在读取 topics.md……'); try { const file = await readFile('topics.md'); topics = parseTopics(file?.text || ''); topicBaseSha = file?.sha; topicBaseline = topics.filter((item) => item.kind === 'topic').map((item) => item.raw); renderTopics(); if (status) setSaved(topicsStatus, file ? '已读取 topics.md。' : 'topics.md 尚不存在；新增选题时会创建。'); return true; } catch (error) { if (status) showError(topicsStatus, error); return false; } }
async function saveTopics(force = false) { if (!requireToken(topicsStatus)) return; showWriteStatus(topicsStatus); try { const baseSha = force ? (await readFile('topics.md'))?.sha : topicBaseSha; const text = serializeTopics(topics); const data = await writeFile('topics.md', text, baseSha); topicBaseSha = savedSha(data, baseSha); topics = parseTopics(text); topicBaseline = topics.filter((item) => item.kind === 'topic').map((item) => item.raw); renderTopics(); setSaved(topicsStatus, baseSha ? '已保存 topics.md。' : '已创建并保存 topics.md。'); } catch (error) { handleWriteError(topicsStatus, error, { reload: loadTopics, overwrite: () => saveTopics(true) }); } }

function deadlineEntries() { return [...tasks.filter((item) => item.kind === 'task' && item.dueDate).map((item) => ({ source: '待办', title: item.title, due: item.dueDate, completed: item.completed, target: 'tasks' })), ...sideworks.filter((item) => item.data.due).map((item) => ({ source: '副业', title: item.data.title || item.file.name, due: item.data.due, completed: item.data.status === 'done', target: 'side' }))]; }
function renderDeadlineReminders() { const panel = document.querySelector('#deadline-panel'); const list = document.querySelector('#deadline-list'); const today = localToday(); const records = deadlineEntries().map((item) => ({ ...item, state: deadlineState(item.due, item.completed, today) })).filter((item) => item.state).sort((a, b) => a.due.localeCompare(b.due)); panel.hidden = records.length === 0; list.replaceChildren(); for (const item of records) { const row = makeButton('', `deadline-row ${item.state}`, () => { switchView(item.target); item.target === 'tasks' ? loadTasks() : loadSideworks(); }); const source = document.createElement('span'); source.className = 'deadline-source'; source.textContent = item.source; const title = document.createElement('strong'); title.textContent = item.title; const due = document.createElement('span'); due.textContent = item.due; const remaining = document.createElement('span'); remaining.textContent = deadlineText(item.due, today); row.append(source, title, due, remaining); list.append(row); } }
function renderToday() { const today = localToday(); const weekday = ['周日', '周一', '周二', '周三', '周四', '周五', '周六'][new Date().getDay()]; document.querySelector('#today-date').textContent = `${today} ${weekday}`; const deadlinePanel = document.querySelector('#today-deadline-panel'); const deadlineList = document.querySelector('#today-deadline-list'); const stateOrder = { overdue: 0, today: 1, soon: 2 }; const deadlines = deadlineEntries().map((item) => ({ ...item, state: deadlineState(item.due, item.completed, today) })).filter((item) => item.state).sort((a, b) => stateOrder[a.state] - stateOrder[b.state] || a.due.localeCompare(b.due)); deadlinePanel.hidden = deadlines.length === 0; deadlineList.replaceChildren(); for (const item of deadlines) { const row = makeButton('', `deadline-row ${item.state}`, () => { switchView(item.target); item.target === 'tasks' ? loadTasks() : loadSideworks(); }); const remaining = document.createElement('span'); remaining.textContent = deadlineText(item.due, today); const title = document.createElement('strong'); title.textContent = item.title; const source = document.createElement('span'); source.className = 'deadline-source'; source.textContent = item.source; row.append(remaining, title, source); deadlineList.append(row); } const planList = document.querySelector('#today-plan-list'); const plans = tasks.filter((item) => item.kind === 'task' && item.plannedDate === today && !item.completed); planList.replaceChildren(); if (!plans.length) { const empty = document.createElement('p'); empty.className = 'today-empty'; empty.textContent = '今天还没安排事情，去待办里挑几件'; planList.append(empty, makeButton('去待办', 'secondary', () => { switchView('tasks'); loadTasks(); })); } else for (const task of plans) { const row = document.createElement('label'); row.className = 'today-task-row'; const check = document.createElement('input'); check.type = 'checkbox'; check.checked = task.completed; check.addEventListener('change', () => updateTask(task, { completed: check.checked })); const title = document.createElement('span'); title.textContent = task.title; row.append(check, title); planList.append(row); } const completedCount = tasks.filter((item) => item.kind === 'task' && item.plannedDate === today && item.completed).length; document.querySelector('#today-completed-title').textContent = completedCount ? `今天完成了 ${completedCount} 件` : '今天完成了 0 件'; document.querySelector('#today-completed-text').textContent = completedCount ? '按计划完成，明天再继续。' : '今天还没勾掉任何一件。'; const guide = document.querySelector('#today-guide'); guide.hidden = hasToken() && Boolean(deadlines.length || plans.length || completedCount || collects.some((item) => item.kind === 'collect')); }
async function loadToday() { if (!hasToken()) { renderToday(); return; } await Promise.all([loadTasks(false), loadSideworks(false), loadCollects(false)]); renderToday(); }
async function loadDeadlineSources() { await Promise.all([loadTasks(false), loadSideworks(false)]); renderDeadlineReminders(); renderCalendar(); }
function monthString(year, month, day) { return `${year}-${String(month + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`; }
function renderCalendar() { const title = document.querySelector('#calendar-title'); const grid = document.querySelector('#calendar-grid'); title.textContent = `${calendarYear} 年 ${calendarMonth + 1} 月`; grid.replaceChildren(); const first = new Date(calendarYear, calendarMonth, 1); const offset = (first.getDay() + 6) % 7; const days = new Date(calendarYear, calendarMonth + 1, 0).getDate(); const today = localToday(); for (let index = 0; index < offset + days; index += 1) { const cell = document.createElement('button'); cell.type = 'button'; cell.className = 'calendar-day'; if (index < offset) { cell.disabled = true; grid.append(cell); continue; } const day = index - offset + 1; const date = monthString(calendarYear, calendarMonth, day); const number = document.createElement('span'); number.textContent = day; cell.append(number); if (date === today) cell.classList.add('today'); const dots = document.createElement('span'); dots.className = 'calendar-dots'; for (const entry of deadlineEntries().filter((item) => item.due === date)) { const dot = document.createElement('i'); dot.className = deadlineState(entry.due, entry.completed, today) === 'overdue' ? 'overdue-dot' : (entry.source === '待办' ? 'task-dot' : 'sidework-dot'); dots.append(dot); } cell.append(dots); cell.addEventListener('click', () => renderCalendarDetails(date)); grid.append(cell); } }
function renderCalendarDetails(date) { const holder = document.querySelector('#calendar-details'); holder.replaceChildren(); const title = document.createElement('h2'); title.textContent = date; holder.append(title); const entries = deadlineEntries().filter((item) => item.due === date); if (!entries.length) { const empty = document.createElement('p'); empty.textContent = '当天没有 DDL。'; holder.append(empty); return; } for (const item of entries) { const row = document.createElement('div'); row.className = 'calendar-entry'; row.textContent = `${item.source} · ${item.title}${item.completed ? '（已完成）' : ''}`; holder.append(row); } }

createNav(); addTokenGuide(); document.querySelector('#app-version').textContent = APP_VERSION; tokenInput.value = localStorage.getItem('penemue-github-token') || ''; renderToday(); loadToday(); if ('serviceWorker' in navigator) { navigator.serviceWorker.addEventListener('controllerchange', () => { if (!reloadForUpdate) return; reloadForUpdate = false; window.location.reload(); }); window.addEventListener('load', () => navigator.serviceWorker.register('./sw.js').then((registration) => { serviceWorkerRegistration = registration; watchForUpdate(registration); showWaitingUpdate(registration); }).catch((error) => console.error('Service Worker 注册失败：', error))); window.addEventListener('focus', checkForUpdateOnFocus); }
tokenInput.addEventListener('input', () => localStorage.setItem('penemue-github-token', tokenInput.value.trim()));
document.addEventListener('click', (event) => { const nav = event.target.closest('.nav-button'); if (!nav) return; switchView(nav.dataset.target); if (nav.dataset.target === 'today') loadToday(); if (nav.dataset.target === 'projects') loadProjects(); if (nav.dataset.target === 'tasks') loadTasks(); if (nav.dataset.target === 'side') loadSideworks(); if (nav.dataset.target === 'inbox') loadCollects(); if (nav.dataset.target === 'notes') loadNotes(); if (nav.dataset.target === 'topics') loadTopics(); if (nav.dataset.target === 'calendar') loadDeadlineSources(); });
document.querySelector('#load-projects-button').addEventListener('click', loadProjects); document.querySelector('#new-task-form').addEventListener('submit', (event) => { event.preventDefault(); addQuickTask(); }); quickTaskInput.addEventListener('input', renderQuickTaskPreview); quickTaskInput.addEventListener('keydown', (event) => { if (event.key !== 'Escape') return; quickTaskInput.value = ''; renderQuickTaskPreview(); }); quickTaskRawButton.addEventListener('click', () => addQuickTask(true)); document.querySelector('#new-sidework-form').addEventListener('submit', (event) => { event.preventDefault(); createSidework(event.currentTarget); });
document.querySelector('#load-notes-button').addEventListener('click', () => loadNotes()); document.querySelector('#reload-notes-button').addEventListener('click', () => loadNotes(true)); document.querySelector('#new-note-form').addEventListener('submit', (event) => { event.preventDefault(); createNote(event.currentTarget); }); document.querySelector('#notes-search').addEventListener('input', renderNotes);
document.querySelector('#new-collect-form').addEventListener('submit', (event) => { event.preventDefault(); if (!requireToken(collectStatus)) return; collects.push(createCollect(new FormData(event.currentTarget).get('content'))); saveCollects(); }); document.querySelector('#today-collect-form').addEventListener('submit', (event) => { event.preventDefault(); const todayStatus = document.querySelector('#today-collect-status'); if (!hasToken()) { showStatus(todayStatus, '请先在设置中填写 GitHub 细粒度 PAT。', 'error'); return; } collects.push(createCollect(new FormData(event.currentTarget).get('content'))); event.currentTarget.reset(); saveCollects(); showStatus(todayStatus, '已记入 collect.md。', 'success'); }); document.querySelector('#note-form').addEventListener('submit', (event) => { event.preventDefault(); organizeAsNote(event.currentTarget); }); document.querySelector('#cancel-note-button').addEventListener('click', () => { organizeTarget = null; document.querySelector('#note-form').hidden = true; });
document.querySelector('#today-settings-button').addEventListener('click', openSettings); document.querySelector('#today-guide-settings-button').addEventListener('click', openSettings);
document.querySelector('#new-topic-form').addEventListener('submit', (event) => { event.preventDefault(); if (!requireToken(topicsStatus)) return; const data = new FormData(event.currentTarget); topics.push(createTopic({ title: data.get('title'), platform: data.get('platform'), status: data.get('status') })); saveTopics(); });
document.querySelector('#calendar-prev').addEventListener('click', () => { if (calendarMonth === 0) { calendarMonth = 11; calendarYear -= 1; } else calendarMonth -= 1; renderCalendar(); }); document.querySelector('#calendar-next').addEventListener('click', () => { if (calendarMonth === 11) { calendarMonth = 0; calendarYear += 1; } else calendarMonth += 1; renderCalendar(); }); document.querySelector('#calendar-today').addEventListener('click', () => { const now = new Date(); calendarMonth = now.getMonth(); calendarYear = now.getFullYear(); renderCalendar(); });
document.addEventListener('focusin', (event) => { if (!event.target.matches('input:not([type="checkbox"]), select, textarea')) return; window.setTimeout(() => event.target.scrollIntoView({ block: 'center', inline: 'nearest', behavior: 'smooth' }), 300); }); document.querySelector('#check-update-button').addEventListener('click', checkForUpdateManually); document.querySelector('#clear-token-button').addEventListener('click', () => { localStorage.removeItem('penemue-github-token'); tokenInput.value = ''; showStatus(result, '已清除这台设备浏览器保存的 token。'); }); document.querySelector('#write-button').addEventListener('click', async () => { if (!requireToken(result)) return; try { const existing = await readFile('test.md'); const content = `Penemue 阶段 0 写入测试。\n写入时间：${new Date().toISOString()}（UTC）。\n这段中文用于验证 UTF-8 Base64 编码没有乱码。\n`; const data = await writeFile('test.md', content, existing?.sha); showStatus(result, `写入成功。\n提交：${data?.commit?.sha || 'GitHub 未返回提交 sha。'}`, 'success'); } catch (error) { showStatus(result, error.message || String(error), 'error'); } }); renderCalendar();
